-- Milestone 10: scheduling + automation
CREATE TABLE "ScheduledJob" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "targetId" TEXT NOT NULL, "intervalMinutes" INTEGER NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "lastRunAt" TIMESTAMP(3), "nextRunAt" TIMESTAMP(3) NOT NULL, "lastStatus" TEXT, "lastError" TEXT, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ScheduledJob_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ScheduledJob_organizationId_enabled_nextRunAt_idx" ON "ScheduledJob"("organizationId","enabled","nextRunAt");
CREATE TABLE "AutomationRule" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "name" TEXT NOT NULL, "campaignPlanId" TEXT, "metric" TEXT NOT NULL, "comparator" TEXT NOT NULL, "threshold" TEXT NOT NULL, "windowDays" INTEGER NOT NULL DEFAULT 3, "action" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "lastEvaluatedAt" TIMESTAMP(3), "lastTriggeredAt" TIMESTAMP(3), "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AutomationRule_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AutomationRule_organizationId_enabled_idx" ON "AutomationRule"("organizationId","enabled");
CREATE TABLE "AutomationRun" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "kind" TEXT NOT NULL, "refId" TEXT NOT NULL, "status" TEXT NOT NULL, "detail" TEXT, "evidence" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AutomationRun_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AutomationRun_organizationId_createdAt_idx" ON "AutomationRun"("organizationId","createdAt");
ALTER TABLE "ScheduledJob" ADD CONSTRAINT "ScheduledJob_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AutomationRule" ADD CONSTRAINT "AutomationRule_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AutomationRun" ADD CONSTRAINT "AutomationRun_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
